def _juntar(partes):
    if isinstance(partes, str):
        return base64.b64decode(partes)
    return base64.b64decode("".join(partes))

def load_image(filename):
    """Carrega uma imagem pelo nome do arquivo (ex: "button.gif")"""
    partes = _ASSETS_B64.get(filename)
    if partes is None:
        raise FileNotFoundError(f'Asset nao encontrado: {filename}')
    dados = _juntar(partes)
    return pygame.image.load(io.BytesIO(dados)).convert_alpha()

def load_image_raw(filename):
    """Retorna os bytes brutos do asset (util para sons, icones, etc.)"""
    partes = _ASSETS_B64.get(filename)
    if partes is None:
        raise FileNotFoundError(f'Asset nao encontrado: {filename}')
    return _juntar(partes)

def load_sound(filename):
    """Carrega um som/musica pelo nome do arquivo (ex: "complete-quest.ogg")"""
    dados = load_image_raw(filename)
    return pygame.mixer.Sound(io.BytesIO(dados))

def list_assets():
    """Retorna lista de todos os assets disponiveis"""
    return list(_ASSETS_B64.keys())
